/*
 * A039056  Numbers whose base-8 representation has the same number of 1's and
 *          2's.
 * https://oeis.org/A039056
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the n-th nonnegative integer whose base‑8 representation
 *            contains * an equal number of digits '1' and '2'. The sequence
 *            is generated by brute‑force * searching over successive integers
 *            and counting the digits
 * Range:     u8 n <= 64, u16 n <= 64, u32 n <= 64, u64 n <= 64, u128 n <= 64,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    idx_t found = 0;      /* how many suitable numbers have been found so far   */
    seq_t x = 0;          /* current integer being tested                      */

    while (found < n) {
        seq_t t = x;      /* copy of x to perform digit extraction            */
        unsigned int c1 = 0, c2 = 0;   /* counters for 1's and 2's                    */

        if (t == 0) {
            /* For x = 0 the base‑8 representation is "0", which has
             * zero 1's and zero 2's, so it is a valid term.          */
        } else {
            while (t) {
                unsigned int d = (unsigned int)(t % 8);
                if (d == 1) ++c1;
                else if (d == 2) ++c2;
                t /= 8;
            }
        }

        if (c1 == c2) {
            ++found;
            if (found == n)
                return x;
        }
        ++x;
    }

    /* The loop always returns before reaching this point, but the
     * compiler requires a return value.                                   */
    return 0;
}
